-- Полное соответствие well-истории, включая удаления, изменения отношений и точный hashdiff.
WITH expected AS (SELECT lower(to_hex(md5(to_utf8('well:' || entity_id)))) AS well_hk,lower(to_hex(md5(to_utf8('well_field:' || entity_id || ':' || json_extract_scalar(payload,'$.field_id'))))) AS link_hk,event_id,entity_version,op,event_time,lower(to_hex(md5(to_utf8(op || ':' || payload)))) AS hashdiff,json_extract_scalar(payload,'$.well_name') AS well_name,try_cast(json_extract_scalar(payload,'$.valid_from') AS date) AS valid_from,json_extract_scalar(payload,'$.status') AS status FROM {{target:oil_dds__event}} WHERE event_type='well'), actual AS (SELECT well_hk,link_hk,event_id,entity_version,op,event_time,hashdiff,well_name,valid_from,status FROM {{target:oil_dds__sat_well}}) SELECT count(*) AS n FROM ((SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)) q;
